"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["78972"],{37042(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.organizacao.unidade.remocao_bloqueada_por_instituicao","status":409,"titulo":"N\xe3o \xe9 poss\xedvel remover uma unidade que \xe9 raiz de uma institui\xe7\xe3o"},"descricao":{"codigo":"uniplus.organizacao.unidade.remocao_bloqueada_por_instituicao","requisitos":["UNI-REQ-0007"],"oQueAconteceu":["A unidade que se tentou remover \xe9 a **unidade raiz** (o v\xednculo com a\\nreitoria) de uma institui\xe7\xe3o viva.","A institui\xe7\xe3o \u2014 o registro singleton que descreve a pr\xf3pria IES \u2014\\nreferencia sua unidade raiz por Id. Remover essa unidade deixaria a\\ninstitui\xe7\xe3o apontando para um registro inexistente, quebrando o v\xednculo\\nque a identifica como reitoria.","Esta \xe9 uma confer\xeancia *check-then-act*: sob concorr\xeancia entre a remo\xe7\xe3o\\ndesta unidade e o cadastro simult\xe2neo de uma institui\xe7\xe3o que a escolhe\\ncomo raiz, o intervalo entre a confer\xeancia e a grava\xe7\xe3o n\xe3o \xe9 protegido por uma\\nrestri\xe7\xe3o de banco \u2014 \xe9 controle de concorr\xeancia ainda em aberto, tratado\\ncomo cross-cutting comum a todos os cadastros, n\xe3o espec\xedfico desta\\nopera\xe7\xe3o."],"comoResolver":["Antes de remover a unidade, atualize a institui\xe7\xe3o para apontar para\\noutra unidade do tipo reitoria como raiz, ou remova a institui\xe7\xe3o\\nprimeiro, se for o caso."],"ondeAparece":["Remo\xe7\xe3o de unidade"]},"modulo":{"id":"organizacao","nome":"Organiza\xe7\xe3o institucional","assunto":"Unidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);